package canonical_test

import (
	"bufio"
	"bytes"
	"crypto/ed25519"
	"crypto/x509"
	"encoding/base64"
	"encoding/json"
	"encoding/pem"
	"os"
	"reflect"
	"strings"
	"testing"
	"unicode/utf8"

	"github.com/toeshee/it-suite/agent/internal/canonical"
)

// corpusCase mirrors one line of testdata/corpus.jsonl, generated by
// scripts/export_canonical_corpus.py from app/jobs/canonical.py::canonical_bytes.
// The Go encoder is pinned to the PYTHON FUNCTION's output, not to anyone's
// reading of CPython's json.encoder.
type corpusCase struct {
	Name      string          `json:"name"`
	Why       string          `json:"why"`
	Input     json.RawMessage `json:"input"`
	Canonical string          `json:"canonical"` // base64 of canonical_bytes(input)
}

func loadCorpus(t *testing.T) []corpusCase {
	t.Helper()
	f, err := os.Open("testdata/corpus.jsonl")
	if err != nil {
		t.Fatalf("%v (regenerate with backend/.venv/bin/python scripts/export_canonical_corpus.py)", err)
	}
	defer f.Close()
	var out []corpusCase
	sc := bufio.NewScanner(f)
	sc.Buffer(make([]byte, 0, 64*1024), 4*1024*1024)
	for sc.Scan() {
		line := bytes.TrimSpace(sc.Bytes())
		if len(line) == 0 {
			continue
		}
		var c corpusCase
		if err := json.Unmarshal(line, &c); err != nil {
			t.Fatalf("corpus line %d: %v", len(out)+1, err)
		}
		out = append(out, c)
	}
	if err := sc.Err(); err != nil {
		t.Fatal(err)
	}
	if len(out) < 15 {
		t.Fatalf("corpus has only %d cases; it is supposed to cover the adversarial set", len(out))
	}
	return out
}

func TestCanonicalMatchesThePythonSigner(t *testing.T) {
	for i, c := range loadCorpus(t) {
		t.Run(c.Name, func(t *testing.T) {
			want, err := base64.StdEncoding.DecodeString(c.Canonical)
			if err != nil {
				t.Fatal(err)
			}
			got, err := canonical.BytesFromRaw(c.Input)
			if err != nil {
				t.Fatalf("BytesFromRaw: %v", err)
			}
			if !bytes.Equal(got, want) {
				t.Fatalf("case %d (%s) diverges from canonical_bytes.\nwhy this case exists: %s\n"+
					" got %q\nwant %q", i, c.Name, c.Why, got, want)
			}
		})
	}
}

// The premise of this package, checked rather than asserted.
//
// docs/modules/agent/plan.md C5 lists four ways encoding/json diverges from
// canonical_bytes. Measured against go1.24.7, THREE of them hold and one does
// not: modern encoding/json emits the \b and \f short forms, exactly like
// Python. That claim was true of older toolchains, which is the point -- the
// behaviour of the standard encoder is a moving target, and an encoder that
// happens to agree on this toolchain is not a contract with a Python function.
//
// This test records, per case, whether the obvious wrong implementation
// (decode into `any`, re-marshal) agrees with the signed bytes. It fails if a
// case moves in either direction, so the justification gets re-read instead of
// assumed. A failure here does not mean the agent is broken.
func TestEncodingJSONIsNotASubstitute(t *testing.T) {
	// name -> does encoding/json.Marshal reproduce canonical_bytes today?
	agreesWithMarshal := map[string]bool{
		// The three real divergences.
		"html_characters":               false, // < > & become < > &
		"line_and_paragraph_separators": false, // U+2028/9 escaped; SetEscapeHTML(false) does NOT help
		"numbers":                       false, // float64: 9007199254740993 -> ...992, -0.0 -> -0, 1e-07 -> 1e-7
		// Agreements. Each is a place a reasonable person would expect a
		// divergence, so each is pinned rather than left to luck.
		"backspace_and_formfeed": true, // go1.24.7 emits \b and \f, unlike older Go
		"control_characters":     true, // lowercase \u00xx, DEL raw -- same as Python
		"non_ascii_passthrough":  true, // raw UTF-8, no \uXXXX
		"non_bmp":                true, // surrogate pair -> one 4-byte sequence
		"short_form_escapes":     true, // and '/' is unescaped by both
		"key_sort_order":         true, // UTF-8 byte order == code point order
	}
	found := 0
	for _, c := range loadCorpus(t) {
		want, ok := agreesWithMarshal[c.Name]
		if !ok {
			continue
		}
		found++
		t.Run(c.Name, func(t *testing.T) {
			signed, _ := base64.StdEncoding.DecodeString(c.Canonical)
			var v any
			if err := json.Unmarshal(c.Input, &v); err != nil {
				t.Fatal(err)
			}
			naive, err := json.Marshal(v)
			if err != nil {
				t.Fatal(err)
			}
			got := bytes.Equal(naive, signed)
			if got != want {
				verb := map[bool]string{true: "now agrees with", false: "no longer agrees with"}[got]
				t.Fatalf("encoding/json %s canonical_bytes for %s -- this package's "+
					"justification changed and must be re-read.\nwhy this case exists: %s\n"+
					"  encoding/json:   %s\n  canonical_bytes: %s",
					verb, c.Name, c.Why, naive, signed)
			}
			t.Logf("marshal agrees=%v\n  encoding/json:   %s\n  canonical_bytes: %s",
				got, naive, signed)
		})
	}
	if found != len(agreesWithMarshal) {
		t.Fatalf("found %d of %d pinned cases in the corpus; a case was renamed or dropped",
			found, len(agreesWithMarshal))
	}
}

// SetEscapeHTML(false) fixes the HTML escapes and nothing else. Reaching for it
// is the near-miss this package exists to prevent: it makes the obvious test
// case pass while U+2028 and every number above 2^53 still differ.
func TestSetEscapeHTMLFalseIsNotEnough(t *testing.T) {
	for _, c := range loadCorpus(t) {
		if c.Name != "line_and_paragraph_separators" && c.Name != "numbers" {
			continue
		}
		t.Run(c.Name, func(t *testing.T) {
			signed, _ := base64.StdEncoding.DecodeString(c.Canonical)
			var v any
			if err := json.Unmarshal(c.Input, &v); err != nil {
				t.Fatal(err)
			}
			var buf bytes.Buffer
			enc := json.NewEncoder(&buf)
			enc.SetEscapeHTML(false)
			if err := enc.Encode(v); err != nil {
				t.Fatal(err)
			}
			relaxed := bytes.TrimRight(buf.Bytes(), "\n")
			if bytes.Equal(relaxed, signed) {
				t.Fatalf("SetEscapeHTML(false) now reproduces canonical_bytes for %s (%s); "+
					"re-read this package's justification", c.Name, relaxed)
			}
			t.Logf("still wrong with SetEscapeHTML(false):\n  got  %s\n  want %s", relaxed, signed)
		})
	}
}

// signedJob mirrors one line of testdata/signed_jobs.jsonl: a whole JobEnvelope
// as the gateway puts it on the wire, signed by the real LocalEd25519Signer.
//
// Canonical bytes agreeing is the necessary half. This is the sufficient half:
// a signature the SERVER produced verifies over bytes the AGENT computed from
// the frame it received. That is invariant #1's mechanism, end to end, across
// the language boundary, with no control plane running.
type signedJob struct {
	Name         string `json:"name"`
	Frame        string `json:"frame"` // the exact JSON text sent on the wire
	Canonical    string `json:"canonical"`
	PublicKeyPEM string `json:"public_key_pem"`
}

func loadSignedJobs(t *testing.T) []signedJob {
	t.Helper()
	raw, err := os.ReadFile("testdata/signed_jobs.jsonl")
	if err != nil {
		t.Fatal(err)
	}
	var out []signedJob
	for _, line := range bytes.Split(bytes.TrimSpace(raw), []byte("\n")) {
		var s signedJob
		if err := json.Unmarshal(line, &s); err != nil {
			t.Fatal(err)
		}
		out = append(out, s)
	}
	if len(out) == 0 {
		t.Fatal("signed_jobs.jsonl is empty")
	}
	return out
}

func parseEd25519PEM(t *testing.T, pemText string) ed25519.PublicKey {
	t.Helper()
	block, _ := pem.Decode([]byte(pemText))
	if block == nil {
		t.Fatal("no PEM block in public_key_pem")
	}
	key, err := x509.ParsePKIXPublicKey(block.Bytes)
	if err != nil {
		t.Fatal(err)
	}
	pub, ok := key.(ed25519.PublicKey)
	if !ok {
		t.Fatalf("public key is %T, want ed25519.PublicKey", key)
	}
	return pub
}

func TestServerSignaturesVerifyOverAgentComputedBytes(t *testing.T) {
	for _, sj := range loadSignedJobs(t) {
		t.Run(sj.Name, func(t *testing.T) {
			// Exactly what the transport will hand the verifier: the raw frame
			// text, from which the `job` member's bytes are taken verbatim.
			var frame struct {
				Job json.RawMessage `json:"job"`
				Sig string          `json:"sig"`
			}
			if err := json.Unmarshal([]byte(sj.Frame), &frame); err != nil {
				t.Fatal(err)
			}
			got, err := canonical.BytesFromRaw(frame.Job)
			if err != nil {
				t.Fatal(err)
			}
			want, _ := base64.StdEncoding.DecodeString(sj.Canonical)
			if !bytes.Equal(got, want) {
				t.Fatalf("canonical bytes differ from the signed bytes\n got %q\nwant %q", got, want)
			}
			sig, err := base64.StdEncoding.DecodeString(frame.Sig)
			if err != nil {
				t.Fatal(err)
			}
			if !ed25519.Verify(parseEd25519PEM(t, sj.PublicKeyPEM), got, sig) {
				t.Fatal("the server's signature does NOT verify over the agent's canonical bytes; " +
					"every job in the fleet would be refused")
			}
			// And the converse: a one-byte change to the bytes must break it,
			// or the verification above proves nothing.
			tampered := append([]byte(nil), got...)
			tampered[len(tampered)-2] ^= 0x01
			if ed25519.Verify(parseEd25519PEM(t, sj.PublicKeyPEM), tampered, sig) {
				t.Fatal("a tampered payload still verified")
			}
		})
	}
}

// Bytes must refuse a Go native number rather than guess at Python's repr.
// Taking the path away is the point: an encoder that formatted a float64
// itself would agree with the corpus and diverge on a customer's params.
func TestBytesRejectsNumbersThatDidNotArriveAsTokens(t *testing.T) {
	for _, v := range []any{
		map[string]any{"n": float64(1)},
		map[string]any{"n": 1},
		map[string]any{"n": int64(1)},
		map[string]any{"a": []any{float64(1.5)}},
		map[string]any{"n": uint8(3)},
	} {
		if b, err := canonical.Bytes(v); err == nil {
			t.Errorf("Bytes(%#v) succeeded, producing %s; native numbers must be refused", v, b)
		}
	}
}

func TestBytesRejectsUnserialisableValues(t *testing.T) {
	// _reject_unknown on the Python side raises TypeError for anything that is
	// not a JSON primitive. The Go side must not silently render it either.
	for _, v := range []any{
		map[string]any{"t": struct{}{}},
		map[string]any{"c": make(chan int)},
		struct{ A int }{1},
		[]byte("raw"),
	} {
		if b, err := canonical.Bytes(v); err == nil {
			t.Errorf("Bytes(%#v) succeeded, producing %s", v, b)
		}
	}
}

func TestBytesAcceptsTheDecodedShapes(t *testing.T) {
	got, err := canonical.BytesFromRaw(json.RawMessage(`{"b":[null,true,1],"a":"x"}`))
	if err != nil {
		t.Fatal(err)
	}
	if string(got) != `{"a":"x","b":[null,true,1]}` {
		t.Fatalf("got %s", got)
	}
}

func TestBytesFromRawRejectsMalformedAndTrailingInput(t *testing.T) {
	cases := map[string]string{
		"truncated":      `{"a":`,
		"trailing bytes": `{"a":1} {"b":2}`,
		"empty":          ``,
		"bare token":     `nope`,
	}
	for name, raw := range cases {
		t.Run(name, func(t *testing.T) {
			if b, err := canonical.BytesFromRaw(json.RawMessage(raw)); err == nil {
				t.Fatalf("accepted %q, producing %s", raw, b)
			}
		})
	}
}

// Canonicalisation is a function of the VALUE, not of how it was written, and
// the server may send params whose keys are in any order.
func TestCanonicalIsIndependentOfInputKeyOrderAndWhitespace(t *testing.T) {
	variants := []string{
		`{"b":1,"a":2}`,
		`{"a":2,"b":1}`,
		"{ \"b\" : 1 ,\n\t\"a\" : 2 }",
	}
	var first []byte
	for _, v := range variants {
		got, err := canonical.BytesFromRaw(json.RawMessage(v))
		if err != nil {
			t.Fatal(err)
		}
		if first == nil {
			first = got
			continue
		}
		if !bytes.Equal(got, first) {
			t.Fatalf("%q canonicalised to %s, but %q gave %s", v, got, variants[0], first)
		}
	}
	if string(first) != `{"a":2,"b":1}` {
		t.Fatalf("got %s", first)
	}
}

// Duplicate keys have no defined meaning and Python's json takes the LAST. The
// agent refuses instead: a frame with a duplicated key is a frame whose signed
// meaning is ambiguous, and guessing at it is how a signature check becomes
// advisory.
func TestBytesFromRawRejectsDuplicateKeys(t *testing.T) {
	if b, err := canonical.BytesFromRaw(json.RawMessage(`{"a":1,"a":2}`)); err == nil {
		t.Fatalf("accepted a duplicated key, producing %s", b)
	} else if !strings.Contains(err.Error(), "duplicate") {
		t.Errorf("error %q does not name the problem", err)
	}
}

func TestCanonicalOutputReparsesToTheSameValue(t *testing.T) {
	for _, c := range loadCorpus(t) {
		t.Run(c.Name, func(t *testing.T) {
			got, err := canonical.BytesFromRaw(c.Input)
			if err != nil {
				t.Fatal(err)
			}
			var a, b any
			d1 := json.NewDecoder(bytes.NewReader(c.Input))
			d1.UseNumber()
			if err := d1.Decode(&a); err != nil {
				t.Fatal(err)
			}
			d2 := json.NewDecoder(bytes.NewReader(got))
			d2.UseNumber()
			if err := d2.Decode(&b); err != nil {
				t.Fatalf("canonical output does not re-parse: %v (%s)", err, got)
			}
			if !reflect.DeepEqual(a, b) {
				t.Fatalf("canonicalisation changed the value\n in %#v\nout %#v", a, b)
			}
		})
	}
}

func FuzzCanonicalRoundTrips(f *testing.F) {
	for _, c := range loadCorpusForFuzz(f) {
		f.Add(string(c))
	}
	f.Add(`{"a":1}`)
	f.Add(`[1,"two",null]`)
	f.Add(`"😀"`)
	f.Fuzz(func(t *testing.T, raw string) {
		got, err := canonical.BytesFromRaw(json.RawMessage(raw))
		if err != nil {
			return // not valid canonicalisable JSON; refusing is the contract
		}
		// 1. The output re-parses to the same value.
		var a, b any
		d1 := json.NewDecoder(strings.NewReader(raw))
		d1.UseNumber()
		if err := d1.Decode(&a); err != nil {
			t.Fatalf("accepted input that does not decode: %q (%v)", raw, err)
		}
		d2 := json.NewDecoder(bytes.NewReader(got))
		d2.UseNumber()
		if err := d2.Decode(&b); err != nil {
			t.Fatalf("output does not re-parse: %q -> %q (%v)", raw, got, err)
		}
		if !reflect.DeepEqual(a, b) {
			t.Fatalf("value changed: %q -> %q", raw, got)
		}
		// 2. Canonicalisation is idempotent. A signature is computed once and
		// checked later; an encoder whose second pass differs would verify at
		// dispatch and fail on a retry.
		again, err := canonical.BytesFromRaw(json.RawMessage(got))
		if err != nil {
			t.Fatalf("own output rejected: %q -> %q (%v)", raw, got, err)
		}
		if !bytes.Equal(got, again) {
			t.Fatalf("not idempotent: %q -> %q -> %q", raw, got, again)
		}
		// 3. The output is valid UTF-8: canonical_bytes ends in .encode("utf-8").
		if !isValidUTF8(got) {
			t.Fatalf("output is not valid UTF-8: %q -> %q", raw, got)
		}
	})
}

func loadCorpusForFuzz(f *testing.F) [][]byte {
	f.Helper()
	raw, err := os.ReadFile("testdata/corpus.jsonl")
	if err != nil {
		f.Fatal(err)
	}
	var out [][]byte
	for _, line := range bytes.Split(bytes.TrimSpace(raw), []byte("\n")) {
		var c corpusCase
		if err := json.Unmarshal(line, &c); err != nil {
			f.Fatal(err)
		}
		out = append(out, c.Input)
	}
	return out
}

func isValidUTF8(b []byte) bool { return utf8.Valid(b) }

// Canonicalisation runs BEFORE signature verification -- it has to, since the
// signature is over its output -- so this decoder is the first code to touch a
// frame off the wire. Unbounded recursion there is a crash-the-agent
// primitive; a refused frame is not.
func TestNestingIsBounded(t *testing.T) {
	deep := strings.Repeat("[", canonical.MaxDepth+2) + strings.Repeat("]", canonical.MaxDepth+2)
	if b, err := canonical.BytesFromRaw(json.RawMessage(deep)); err == nil {
		t.Fatalf("accepted nesting deeper than MaxDepth=%d, producing %d bytes",
			canonical.MaxDepth, len(b))
	} else if !strings.Contains(err.Error(), "nesting") {
		t.Errorf("error %q does not name the problem", err)
	}
	// ...and a realistic depth is nowhere near the bound.
	ok := strings.Repeat("[", 64) + strings.Repeat("]", 64)
	if _, err := canonical.BytesFromRaw(json.RawMessage(ok)); err != nil {
		t.Fatalf("refused ordinary nesting: %v", err)
	}
}
